// One original A-frame mesh extracted from the user's Chalkboard_sign_V1 GLB.
// Source: clon6767 on Sketchfab, CC BY 4.0. Coordinates quantized to 0.01 source units.
// Four instances in the upload were reduced to one; original triangle topology preserved.
export const TRANSLATION_SIGN_TEXT={
 title:'THE TRANSLATION AREA',
 lines:[
  'Four images from',
  'PROPORTION PIECE,',
  'reinterpreted through',
  'TouchDesigner as',
  'moving digital artworks.'
 ],
 symbol:'φ'
};
const MESH='';
// Entrance-side placement is tied to the actual public glass doorway and
// actual gramophone cabinet, rather than the unrelated backroom entrance.
export const TRANSLATION_SIGN_SCALE=1.65; // 0.995m -> 1.64m tall, legible beside the gramophone.
export function translationAreaSignPlacement(entrance,gramophone,{scale=TRANSLATION_SIGN_SCALE}={}){
 if(!entrance || !gramophone || !['x','z'].includes(entrance.axis))return null;
 if(!Number.isFinite(entrance.at)||!Number.isFinite(entrance.centre)||
    !Number.isFinite(gramophone.x)||!Number.isFinite(gramophone.z))return null;
 const across=entrance.axis==='z'?'x':'z';
 const inward=entrance.axis==='z'?'z':'x';
 const door={x:entrance.axis==='z'?entrance.centre:entrance.at,
             z:entrance.axis==='x'?entrance.centre:entrance.at};
 const difference=gramophone[across]-door[across];
 const side=Math.sign(difference)||1;
 // Offset along the doorway wall so the enlarged 0.69m-wide A-frame and
 // a 0.3m margin sit entirely OUTSIDE the glass door's swing/clear opening.
 const doorWidth=Number.isFinite(entrance.width)?entrance.width:2.8;
 const half=doorWidth/2;
 const signRadius=.42*scale/2;
 const requiredLateralClearance=half+signRadius+.3;
 const between=Math.abs(difference)-.9;
 // Aim to be between the door and gramophone but keep door opening clear.
 // The door frame still occluded half the board: shift it along the wall,
 // to the gramophone side and clear of the glazing, not deeper through the door.
 const lateral=Math.max(requiredLateralClearance,
   Math.min(Math.max(requiredLateralClearance,between),Math.abs(difference)*.57)) + 1.3;
 const centre={
  ...door,
  [across]:door[across]+side*lateral,
  [inward]:door[inward]+Math.max(-.95,Math.min(.95,
   (gramophone[inward]-door[inward])*.42))
 };
 // Stay on the reception side of the glass; lateral separation clears its frame.
 const distanceToGramophone=Math.hypot(centre.x-gramophone.x,centre.z-gramophone.z);
 const distanceToDoor=Math.hypot(centre.x-door.x,centre.z-door.z);
 // If there is too little room, do not let a freestanding sign clip the
 // music cabinet: pull it 0.35m closer to the doorway's interior side.
 if(distanceToGramophone<1.1){
  const move=Math.sign(gramophone[inward]-door[inward])||1;
  centre[inward]-=move*.42;
 }
 const distanceToGramophoneFinal=Math.hypot(centre.x-gramophone.x,centre.z-gramophone.z);
 // Front of the board faces the reception interior and approaching visitors.
 const normal={x:0,z:0};
 normal[inward]=Math.sign(gramophone[inward]-door[inward])||1;
 return {
  x:centre.x,z:centre.z,yaw:Math.atan2(normal.x,normal.z),normal,
  zone:'reception-main-door-gramophone',axis:entrance.axis,doorAt:entrance.at,
  doorCentre:entrance.centre,doorWidth,side,scale,
  gramophone:{x:gramophone.x,z:gramophone.z},
  door:{x:door.x,z:door.z},
  distanceToDoor,distanceToGramophone:distanceToGramophoneFinal,
  lateralClearance:Math.abs(centre[across]-door[across])-(half+signRadius)
 };
}
function meshGeometry(THREE){
 const binary=atob(MESH),view=new DataView(Uint8Array.from(binary,c=>c.charCodeAt(0)).buffer);
 const vertices=view.getUint16(0,true),faces=view.getUint16(2,true);
 const positions=new Float32Array(vertices*3);
 for(let i=0;i<vertices*3;i++)positions[i]=view.getInt16(4+i*2,true)/10000;
 const indices=new Uint16Array(faces*3);
 for(let i=0;i<faces*3;i++)indices[i]=view.getUint16(4+vertices*6+i*2,true);
 const geo=new THREE.BufferGeometry();
 geo.setAttribute('position',new THREE.BufferAttribute(positions,3));
 geo.setIndex(new THREE.BufferAttribute(indices,1));
 geo.computeVertexNormals();
 return geo;
}
export function addPhiTranslationAreaSign(THREE,scene,{entrance,gramophone,elevation=0}){
 const place=translationAreaSignPlacement(entrance,gramophone);
 if(!place)return null;
 // After the approved 180-degree turn, move backward by 2m toward the wall.
 // Backward in world space is +yaw's original normal (the front is yaw+PI).
 place.x+=Math.sin(place.yaw)*2;
 place.z+=Math.cos(place.yaw)*2;
 place.backwardOffsetMetres=2;
 place.distanceToDoor=Math.hypot(place.x-place.door.x,place.z-place.door.z);
 place.distanceToGramophone=Math.hypot(place.x-place.gramophone.x,place.z-place.gramophone.z);
 return buildPhiTranslationAreaSign(THREE,scene,place,{
  name:'phi-translation-area-doorway-sign',rotation:place.yaw+Math.PI,elevation
 });
}
function buildPhiTranslationAreaSign(THREE,scene,place,{name,rotation,elevation=0}){
 const root=new THREE.Group();
 root.name=name;
 root.userData.kind='gallery-label';
 root.position.set(place.x,elevation+.016,place.z);
 root.rotation.y=rotation; // The original sign keeps its approved 180-degree facing.
 root.scale.setScalar(place.scale);
 const mesh=new THREE.Mesh(meshGeometry(THREE),
  new THREE.MeshStandardMaterial({color:'#80614a',roughness:.94,side:THREE.DoubleSide}));
 // Original 0.42m × 0.995m × 0.34m A-frame, enlarged 65% to a ~1.64m entrance sign.
 root.add(mesh);
 const canvas=document.createElement('canvas');canvas.width=768;canvas.height=1450;
 const ctx=canvas.getContext('2d',{alpha:false});
 const cw=canvas.width,ch=canvas.height;
 ctx.fillStyle='#18373a';ctx.fillRect(0,0,cw,ch);
 ctx.strokeStyle='rgba(250,243,225,.3)';ctx.lineWidth=9;ctx.strokeRect(20,20,cw-40,ch-40);
 ctx.textAlign='center';
 ctx.fillStyle='#f0eadd';ctx.font='58px Georgia, serif';
 ctx.fillText('THE TRANSLATION',cw/2,175,cw-95);
 ctx.fillText('AREA',cw/2,255,cw-95);
 ctx.strokeStyle='#d7c6a7';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(90,310);ctx.lineTo(cw-90,310);ctx.stroke();
 // Both A-frame signs share this canvas. Keep the caption short and the φ prominent.
 ctx.fillStyle='#f0eadc';ctx.font='50px Georgia, serif';
 TRANSLATION_SIGN_TEXT.lines.forEach((line,i)=>ctx.fillText(line,cw/2,440+i*105,cw-100));
 ctx.fillStyle='#d9c9aa';ctx.font='310px Georgia, serif';
 ctx.fillText(TRANSLATION_SIGN_TEXT.symbol,cw/2,1250,cw-100);
 const texture=new THREE.CanvasTexture(canvas);
 texture.colorSpace=THREE.SRGBColorSpace;
 texture.anisotropy=4;
 const panel=new THREE.Mesh(new THREE.PlaneGeometry(.355,.734),
  new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide,toneMapped:false}));
 // Align with the original chalkboard face (the slope is present in the mesh).
 panel.position.set(0,.565,.087);
 panel.rotation.x=-Math.atan(11.16/79.38);
 panel.name='translation-area-curatorial-label';
 root.add(panel);
 scene.add(root);
 root.userData.placement=place;
 return {root,placement:place,meshFaces:152,dispose(){
  scene.remove(root);
  mesh.geometry.dispose();mesh.material.dispose();
  panel.geometry.dispose();panel.material.dispose();texture.dispose();
 }};
}

// Place an identical Translation Area sign OUTSIDE the door to the room
// with the two large screens, specifically on the main-reception side.
// Circulation's a/b room indices identify the *real* connecting door;
// guessing the nearest door risks placing a sign in the wrong backroom.
export function planPhiLargeMonitorDoorSign({
 rearRoom,foyerRoomIndex,doors=[],floor,physicalWalls=[],scale=TRANSLATION_SIGN_SCALE
}={}){
 if(!rearRoom||!Number.isInteger(rearRoom.room)||!Number.isInteger(foyerRoomIndex)||
    rearRoom.room===foyerRoomIndex||!floor?.mergedRooms?.[foyerRoomIndex])return null;
 const door=doors.find(d=>(d.a===rearRoom.room&&d.b===foyerRoomIndex)||
                           (d.b===rearRoom.room&&d.a===foyerRoomIndex));
 if(!door||!Number.isFinite(door.centre)||!Number.isFinite(door.at)||
    !Number.isFinite(door.width)||!['x','z'].includes(door.axis))return null;
 const foyer=floor.mergedRooms[foyerRoomIndex];
 const inFoyer=(x,z,margin=.46)=>foyer.pieces.some(p=>
  x>=p.x+margin&&x<=p.x+p.w-margin&&z>=p.z+margin&&z<=p.z+p.h-margin);
 const x0=door.axis==='x'?door.at:door.centre;
 const z0=door.axis==='z'?door.at:door.centre;
 const lateral=door.width/2+(.42*scale)/2+.38;
 const normalOptions=door.axis==='x'?[{x:-1,z:0},{x:1,z:0}]:
                                     [{x:0,z:-1},{x:0,z:1}];
 const normal=normalOptions.find(n=>inFoyer(x0+n.x*1,z0+n.z*1,.40));
 if(!normal)return null; // Never place the sign on the monitor-room side.
 const tangent=door.axis==='x'?{x:0,z:1}:{x:1,z:0};
 const candidates=[-1,1].map(side=>({
  x:x0+normal.x*.95+tangent.x*lateral*side,
  z:z0+normal.z*.95+tangent.z*lateral*side,
  side
 }));
 // A-frame footprint plus a walking margin must be inside the foyer,
 // not inside a wall, the doorway, or the separate monitor room.
 const safety=.45;
 const wallDistance=p=>physicalWalls.reduce((best,w)=>{
  const offset=w.axis==='x'?Math.abs(p.x-w.at):Math.abs(p.z-w.at);
  const coordinate=w.axis==='x'?p.z:p.x;
  const spanGap=Math.max(w.lo-coordinate,0,coordinate-w.hi);
  return Math.min(best,Math.hypot(offset,spanGap));
 },Infinity);
 const safe=candidates.filter(p=>inFoyer(p.x,p.z,safety)&&
                                    wallDistance(p)>.52);
 if(!safe.length)return null;
 safe.sort((a,b)=>wallDistance(b)-wallDistance(a));
 const chosen=safe[0];
 const placement={
  ...chosen,yaw:Math.atan2(normal.x,normal.z),normal,
  scale,zone:'reception-large-monitor-room-door',
  door:{x:x0,z:z0},doorAxis:door.axis,doorWidth:door.width,
  doorRooms:[door.a,door.b],rearRoom:rearRoom.room,
  foyerRoom:foyerRoomIndex,lateralClearance:lateral-door.width/2-(.42*scale)/2,
  distanceToDoor:Math.hypot(chosen.x-x0,chosen.z-z0)
 };
 return placement;
}
export function addPhiLargeMonitorDoorSign(THREE,scene,{
 rearRoom,foyerRoomIndex,doors,floor,physicalWalls,elevation=0
}={}){
 const place=planPhiLargeMonitorDoorSign({
  rearRoom,foyerRoomIndex,doors,floor,physicalWalls
 });
 if(!place)return null;
 // Reuse the same approved uploaded 152-face A-frame and the same canvas
 // lettering as the existing Translation Area sign. Its front faces the foyer.
 return buildPhiTranslationAreaSign(THREE,scene,{
  ...place,yaw:place.yaw
 },{name:'phi-translation-area-large-monitor-entrance-sign',rotation:place.yaw,elevation});
}

// A second copy of the same credited A-frame, beside reception's lift.
export function towerLiftSignPlacement(lift,entrance){
 if(!lift?.portal||!entrance)return null;
 const x=lift.portal.at+1,z=lift.portal.centre+2.05;
 const door={x:entrance.axis==='z'?entrance.centre:entrance.at,
  z:entrance.axis==='x'?entrance.centre:entrance.at};
 return {x,z,yaw:Math.atan2(door.x-x,door.z-z),scale:TRANSLATION_SIGN_SCALE};
}
export function addPhiTowerLiftSign(THREE,scene,{lift,entrance,elevation=0}){
 const place=towerLiftSignPlacement(lift,entrance);if(!place)return null;
 const root=new THREE.Group();root.name='phi-daily-tower-lift-sign';
 root.userData.kind='gallery-label';
 root.position.set(place.x,elevation+.016,place.z);
 root.rotation.y=place.yaw;root.scale.setScalar(place.scale);
 const frame=new THREE.Mesh(meshGeometry(THREE),new THREE.MeshStandardMaterial({
  color:'#80614a',roughness:.94,side:THREE.DoubleSide}));root.add(frame);
 const canvas=document.createElement('canvas');canvas.width=768;canvas.height=1450;
 const g=canvas.getContext('2d',{alpha:false});
 g.fillStyle='#18373a';g.fillRect(0,0,768,1450);
 g.strokeStyle='rgba(250,243,225,.3)';g.lineWidth=9;g.strokeRect(20,20,728,1410);
 g.textAlign='center';g.fillStyle='#f0eadd';g.font='58px Georgia, serif';
 g.fillText('THE DAILY',384,160,650);g.fillText('GALLERY TOWER',384,240,650);
 g.strokeStyle='#d7c6a7';g.lineWidth=3;g.beginPath();g.moveTo(90,290);g.lineTo(678,290);g.stroke();
 g.fillStyle='#d9c9aa';g.font='italic 37px Georgia, serif';
 g.fillText('A new collection. A new floor.',384,365,660);
 g.fillStyle='#f0eadc';g.font='43px Georgia, serif';
 const lines=['Each day, new studies','become a new exhibition','floor above reception.','','Take this lift to explore','the growing tower.'];
 lines.forEach((line,i)=>{if(line)g.fillText(line,384,475+i*91,650);});
 g.strokeStyle='#d7c6a7';g.beginPath();g.moveTo(90,1040);g.lineTo(678,1040);g.stroke();
 g.fillStyle='#d9c9aa';g.font='38px Georgia, serif';g.fillText('USE THE LIFT CALENDAR',384,1120,650);
 g.fillStyle='#f0eadc';g.font='39px Georgia, serif';
 g.fillText('Choose a date to visit its floor.',384,1205,650);
 g.fillText('Return here via Reception.',384,1275,650);
 g.font='28px Georgia, serif';g.fillText('PROPORTION PIECE',384,1390,650);
 const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=4;
 const material=new THREE.MeshBasicMaterial({map:texture,toneMapped:false});
 for(const side of [1,-1]){
  const panel=new THREE.Mesh(new THREE.PlaneGeometry(.355,.734),material);
  panel.position.set(0,.565,side*.087);
  panel.rotation.set(-side*Math.atan(11.16/79.38),side===1?0:Math.PI,0);
  panel.name='daily-tower-lift-information-'+(side===1?'front':'back');root.add(panel);
 }
 root.userData.placement=place;scene.add(root);return {root,placement:place};
}
